    private static float[] concat(float[]... parts) {
        var length = 0;
        for (var part : parts) {
            length += part.length;
        }
        var out = new float[length];
        var offset = 0;
        for (var part : parts) {
            System.arraycopy(part, 0, out, offset, part.length);
            offset += part.length;
        }
        return out;
    }
